//! Which icon a file gets, and the icons themselves.
//!
//! The set is the Material Icon Theme's (MIT, `assets/icons/LICENSE`),
//! taken from its published extension since M8.13, and so is the table of
//! associations — generated by the theme's own build rather than typed, because `.tsx` is `react_ts`
//! and not `typescript`, and `package.json` beats `.json` only because a
//! whole name outranks an extension. Transcribing that by hand is how a
//! set drifts into looking *almost* like the theme people know.
//!
//! This file is the one hand-written half: the rule that turns a name into
//! a stem, with its tests, and since M8.13 the file's language asked
//! last, as the theme's host asks its language registry. Everything it can
//! answer is checked against the files in the set, because the failure
//! mode of a missing icon is a row that silently draws nothing.
//!
//! `map.rs` and `embed.rs` are GENERATED by `scripts/vendor-icons.py`.

use std::borrow::Cow;

use gpui::{AssetSource, SharedString, Styled, img, svg};

mod embed;
mod map;

/// What an unmatched file gets. Upstream's `fileIcons.defaultIcon`.
const DEFAULT_FILE: &str = "file";

/// What an unmatched directory gets, before the `-open` suffix.
const DEFAULT_FOLDER: &str = "folder";

/// Whether the palette is light: the set has a `_light` variant for the
/// icons that would vanish on a light canvas.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Palette {
    /// The four dark palettes.
    Dark,
    /// The one light palette.
    Light,
}

impl From<crate::theme::Kind> for Palette {
    fn from(kind: crate::theme::Kind) -> Self {
        if kind.is_light() {
            Self::Light
        } else {
            Self::Dark
        }
    }
}

/// A lookup in one of the generated tables, which are sorted by key.
fn lookup(table: &[(&'static str, &'static str)], key: &str) -> Option<&'static str> {
    table
        .binary_search_by_key(&key, |(k, _)| k)
        .ok()
        .map(|i| table[i].1)
}

/// The stem of a file's icon.
///
/// The whole name first — `package.json` is `nodejs`, not `json` — then
/// the suffixes from the longest: `a.b.c` offers `b.c`, then `c`. The
/// loop starts at the second component so that the whole name never
/// reaches the extension table; that is the first step's job, and a name
/// reachable by two rules is a name that changes when one of them does.
pub fn for_file(name: &str, palette: Palette) -> String {
    let lower = name.to_lowercase();
    let stem = lookup(map::BY_FILENAME, &lower)
        .or_else(|| {
            let parts: Vec<&str> = lower.split('.').collect();
            (1..parts.len()).find_map(|i| lookup(map::BY_EXTENSION, &parts[i..].join(".")))
        })
        .or_else(|| by_language(&lower))
        .unwrap_or(DEFAULT_FILE);
    themed(stem, palette)
}

/// The icon the theme gives a file's **language**, asked last.
///
/// The theme leans on its host editor's language registry for two things its
/// own tables do not carry. **A type it knows only by language id**: `ts`,
/// `js`, `yml` and `php` are in neither file table, and `languageIds` answers
/// all four. And **a name it does not list at all**: `.zshrc` and `.bashrc`
/// are nowhere in it, because the registry calls them `shellscript` and the
/// theme answers the language.
///
/// Guild has a language table of its own — `highlight::Language::of`,
/// the same rule, whole name then longest suffix — so it stands in for
/// that registry. The language's name is tried first, and then its
/// **canonical suffix**, because our names and the theme's language ids
/// agree for most languages and not for all: ours is `bash` where its id
/// is `shellscript`, and `sh` reaches the same icon without a table of
/// aliases that would have to be kept in step by hand.
fn by_language(lower: &str) -> Option<&'static str> {
    let language = crate::highlight::Language::of(std::path::Path::new(lower))?;
    lookup(map::BY_LANGUAGE, language.name).or_else(|| {
        language
            .suffixes
            .iter()
            .find_map(|suffix| lookup(map::BY_EXTENSION, suffix))
    })
}

/// The stem of a directory's icon: the folder table by the name, then by
/// the name with one leading `.`, `_` or `-` or a `__wrapping__` looked
/// through — `.github` is `github`, `__tests__` is `tests` — then the
/// plain folder; `-open` when it is expanded.
pub fn for_dir(path: &std::path::Path, expanded: bool, palette: Palette) -> String {
    let stem = match role(path) {
        Role::Source => "folder-src",
        Role::Test => "folder-test",
        Role::Resources => "folder-resource",
        Role::Plain => DEFAULT_FOLDER,
    };
    let stem = if expanded {
        format!("{stem}-open")
    } else {
        stem.to_owned()
    };
    themed(&stem, palette)
}

/// What a directory is **for**, which is the only thing its icon says
/// since M8.12.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Role {
    /// Where a module's code lives: `src`, `src/main/kotlin`.
    Source,
    /// Where its tests live: `src/test/java`, `tests`.
    Test,
    /// What it ships beside the code: `src/main/resources`.
    Resources,
    /// Everything else, and it is most of a tree.
    Plain,
}

/// The languages a source root is named after under `src/main` and
/// `src/test` — Gradle's and Maven's layout, which is where the shape
/// comes from.
const LANGUAGES: &[&str] = &["java", "kotlin", "scala", "groovy", "clojure", "resources"];

/// What a directory is for, **read off its path and not its name**.
///
/// **M8.12.** The Material Icon Theme picks a folder's icon
/// by its name, so a `configuration` package wore a gear, `web` a globe
/// and `build` a crate — a tree of a Kotlin project came out in six
/// colours, none of which said anything about the code. What deserves a
/// colour is what the build system knows: a source root, a test root, what is
/// resources. Guild has no build system, so the shape of the path stands
/// in for it, and everything else is a plain folder.
pub fn role(path: &std::path::Path) -> Role {
    let parts: Vec<String> = path
        .components()
        .map(|part| part.as_os_str().to_string_lossy().to_lowercase())
        .collect();
    let Some(last) = parts.last() else {
        return Role::Plain;
    };
    let under = |what: &str| -> bool {
        // `…/src/<what>/<last>` — a language directory under a source or
        // a test tree.
        parts.len() >= 3
            && LANGUAGES.contains(&last.as_str())
            && parts[parts.len() - 2] == what
            && parts[parts.len() - 3] == "src"
    };
    if last == "resources" {
        return Role::Resources;
    }
    if under("test")
        || matches!(
            last.as_str(),
            "test" | "tests" | "__tests__" | "spec" | "specs"
        )
    {
        return Role::Test;
    }
    if under("main") || last == "src" {
        return Role::Source;
    }
    Role::Plain
}

/// The light variant where the set has one, the stem itself otherwise —
/// never a file that is not there.
fn themed(stem: &str, palette: Palette) -> String {
    if palette == Palette::Light && map::HAS_LIGHT_VARIANT.binary_search(&stem).is_ok() {
        format!("{stem}_light")
    } else {
        stem.to_owned()
    }
}

/// Every stem the rule can answer, in both palettes: what the test walks
/// against the set.
pub fn stems() -> impl Iterator<Item = String> {
    let files = map::BY_FILENAME
        .iter()
        .chain(map::BY_EXTENSION)
        .chain(map::BY_LANGUAGE)
        .map(|(_, stem)| (*stem).to_owned())
        .chain([DEFAULT_FILE.to_owned()]);
    // **The whole folder table, though `for_dir` answers four stems since
    // M8.12.** The set is somebody else's repository and the table is
    // generated from it; walking all of it is what catches a vendoring
    // that dropped a file, and the day a folder role comes back the
    // guard is already there.
    let folders = map::BY_FOLDER
        .iter()
        .map(|(_, stem)| *stem)
        .chain([
            DEFAULT_FOLDER,
            "folder-src",
            "folder-test",
            "folder-resource",
        ])
        .flat_map(|stem| [stem.to_owned(), format!("{stem}-open")]);
    files
        .chain(folders)
        .flat_map(|stem| [themed(&stem, Palette::Light), stem])
}

/// Whether a file of that name is in the set.
pub fn has(file_name: &str) -> bool {
    embed::bytes(file_name).is_some()
}

/// The licence the artwork is under, as it travels with the set.
pub fn licence() -> &'static str {
    include_str!("../../assets/icons/LICENSE")
}

/// An icon at the size the tree row and the tab give it: 16, section 6.4.
pub(crate) fn icon(stem: &str) -> gpui::Img {
    img(SharedString::from(format!("icons/{stem}.svg"))).size(crate::theme::space::ICON)
}

/// Workspace marks offered by the picker, in stable wire order.
pub const WORKSPACE_NAMES: &[&str] = guild_session::ICONS;

/// Whether a persisted named icon is one this build offers.
pub fn is_workspace_name(name: &str) -> bool {
    WORKSPACE_NAMES.contains(&name)
}

