/// The icons **`gpui-component` asks us for**, by the names it asks for.
///
/// It draws its own controls — the editor's find panel, and whatever else
/// of it we come to use — with `IconName`, whose `path()` is
/// `icons/<lucide-name>.svg`, and it **ships no assets at all**: the
/// application is expected to serve that namespace. Guild never did, so
/// every button the component drew for itself was blank. Task 0 of M8.7
/// found the find panel's five that way: the field looked like a field
/// with nothing beside it, and the five buttons were there, hit-testable,
/// and invisible. It is the `UI` trap from the other side — `load`
/// answers `None`, GPUI paints emptiness, and nothing says so.
///
/// **This is a separate table, not an extension of the Material set.**
/// `icons/` is also where the file-type icons live, and they are 422
/// names from somebody else's repository: the day one of them is called
/// `close.svg`, a file-type icon would be handed to the component's close
/// button. The component's names are answered from here first and the
/// file set is never consulted for one of them.
///
/// The files sit in `assets/component`, named exactly as the component
/// asks for them: a separate directory for a separate namespace, so that
/// the walk over `assets/ui` and the walk over this one are two tests
/// that cannot be confused for each other.
///
/// Lucide's again, ISC, the licence beside the files: `chevron-left`,
/// `chevron-right`, `chevron-down`, `x` — which the component calls `close` —
/// `case-sensitive` and `replace`.
pub const COMPONENT: &[(&str, &[u8])] = &[
    (
        "icons/chevron-down.svg",
        include_bytes!("../../assets/component/chevron-down.svg"),
    ),
    (
        "icons/chevron-left.svg",
        include_bytes!("../../assets/component/chevron-left.svg"),
    ),
    (
        "icons/chevron-right.svg",
        include_bytes!("../../assets/component/chevron-right.svg"),
    ),
    (
        "icons/close.svg",
        include_bytes!("../../assets/component/close.svg"),
    ),
    (
        "icons/case-sensitive.svg",
        include_bytes!("../../assets/component/case-sensitive.svg"),
    ),
    (
        "icons/replace.svg",
        include_bytes!("../../assets/component/replace.svg"),
    ),
    // The spinner beside a language server's work, M8.5.1.
    (
        "icons/loader.svg",
        include_bytes!("../../assets/component/loader.svg"),
    ),
];

/// A tool's icon for the status bar's button. Like every svg here it is
/// drawn only in a colour set on it with `text_color` — GPUI does not
/// inherit a parent's (`docs/traps.md`). Lucide's `folder`,
/// `git-commit-horizontal`, `history`, `square-terminal`, `search`,
/// `circle-alert` and `text-search`, under the licence beside the chevrons.
pub(crate) fn tool(tool: guild_session::Tool) -> gpui::Svg {
    gpui::svg()
        .path(match tool {
            guild_session::Tool::Explorer => "ui/rail-explorer.svg",
            guild_session::Tool::Commit => "ui/rail-changes.svg",
            guild_session::Tool::Git => "ui/rail-log.svg",
            guild_session::Tool::Output => "ui/rail-output.svg",
            guild_session::Tool::Terminal => "ui/mark-terminal.svg",
            guild_session::Tool::Search => "ui/rail-search.svg",
            guild_session::Tool::Problems => "ui/rail-problems.svg",
            guild_session::Tool::Push => "ui/rail-push.svg",
            guild_session::Tool::Find => "ui/rail-find.svg",
        })
        .size(crate::theme::space::STATUS_ICON)
}

/// A checkbox's tick, drawn in the colour set on it — never a parent's.
pub(crate) fn check() -> gpui::Svg {
    gpui::svg()
        .path("ui/check.svg")
        .size(crate::theme::space::CHECK)
}

/// A checkbox's partial tick — GLD-026 — at the tick's size and weight.
pub(crate) fn check_partial() -> gpui::Svg {
    gpui::svg()
        .path("ui/check-partial.svg")
        .size(crate::theme::space::CHECK)
}

/// A toolbar button's icon by its asset name, at the head's size,
/// drawn in the colour set on it — never a parent's or a button's.
pub(crate) fn toolbar(name: &'static str) -> gpui::Svg {
    gpui::svg().path(name).size(crate::theme::space::HEAD_ICON)
}

/// The crosshair, drawn in the colour set on it — never a parent's.
pub(crate) fn crosshair() -> gpui::Svg {
    gpui::svg()
        .path("ui/crosshair.svg")
        .size(crate::theme::space::HEAD_ICON)
}

/// **A glyph that was a character in a line of text**, drawn as its icon
/// at that text's size so nothing beside it moves: `⎇`, `★`, `▾`, `✓`,
/// `✕`, `+` were the UI face's idea of those shapes, a different one in
/// every face and none of them the icon the rest of the window draws.
/// The colour is the caller's, set on this svg — never a parent's
/// (`docs/traps.md`).
pub(crate) fn glyph(path: &'static str, size: gpui::Rems) -> gpui::Svg {
    svg().path(path).flex_none().size(size)
}

/// **A disclosure chevron standing inline where a `▾` or `▸` stood**, after a
/// word: Lucide draws it in the middle 14 of its 24, so the square box was
/// wider than the character and pushed whatever came after it along —
/// the title bar's update arrow, each Log filter after the first. The box
/// takes about the character's width — the ink's 14 of 24 and a sliver
/// either side, 16 — and the icon, at its full size, is centred in it and
/// reaches past it evenly, into nothing but the gaps.
pub(crate) fn inline_chevron(open: bool, size: gpui::Rems, colour: u32) -> gpui::Div {
    use gpui::prelude::*;
    gpui::div()
        .flex_none()
        .w(gpui::Rems(size.0 * 16.0 / 24.0))
        .h(size)
        .flex()
        .items_center()
        .justify_center()
        .child(
            glyph(
                if open {
                    "ui/chevron-down.svg"
                } else {
                    "ui/chevron-right.svg"
                },
                size,
            )
            .text_color(gpui::rgb(colour)),
        )
}

/// A round mark where a `●` was — an activity dot's shape, in a colour.
pub(crate) fn dot(colour: u32) -> gpui::Div {
    use gpui::prelude::*;
    gpui::div()
        .flex_none()
        .size(crate::theme::activity::DOT)
        .rounded_full()
        .bg(gpui::rgb(colour))
}

/// Where a `○` was: the dot's outline, in a colour.
pub(crate) fn ring(colour: u32) -> gpui::Div {
    use gpui::prelude::*;
    gpui::div()
        .flex_none()
        .size(crate::theme::activity::DOT)
        .rounded_full()
        .border_1()
        .border_color(gpui::rgb(colour))
}

/// A directory's disclosure arrow, pointing down when it is expanded.
pub(crate) fn chevron(expanded: bool) -> gpui::Svg {
    svg()
        .path(if expanded {
            "ui/chevron-down.svg"
        } else {
            "ui/chevron-right.svg"
        })
        .size(crate::theme::space::CHEVRON)
}

