/// A row of *External Libraries*: the library icon, or the JDK icon —
/// M8.14. The `_dark` file on a dark palette, as [`for_declaration`] says.
pub fn for_library(jdk: bool, palette: Palette) -> String {
    let stem = if jdk { "jdk" } else { "library" };
    match palette {
        Palette::Dark => format!("nodes/{stem}_dark"),
        Palette::Light => format!("nodes/{stem}"),
    }
}

/// The stem of the icon for what a file declares.
///
/// **The dark palettes take the `_dark` file.** JetBrains names the
/// variant for the canvas it is drawn on and the Material Icon Theme
/// names it for the one it is *not* — `rust.svg` is the dark one there
/// and `rust_light.svg` the exception. Two sets, two conventions, and
/// nothing to be done but say which is which.
pub fn for_declaration(kind: crate::declaration::Kind, palette: Palette) -> String {
    use crate::declaration::Kind;
    let stem = match kind {
        Kind::Class => "class",
        Kind::Abstract => "classAbstract",
        Kind::Interface => "interface",
        Kind::Enum => "enum",
        Kind::Annotation => "annotation",
        Kind::Record => "record",
    };
    match palette {
        Palette::Dark => format!("nodes/{stem}_dark"),
        Palette::Light => format!("nodes/{stem}"),
    }
}

/// The set, as GPUI asks for it: an `img("icons/rust.svg")` resolves here.
///
/// The trait's `Result` is `gpui::Result`, which is `anyhow`'s; the
/// crate's own rule keeps `anyhow` to `main.rs`, and this is the trait's
/// signature rather than a choice of ours — nothing here can fail.
pub struct Icons;

impl AssetSource for Icons {
    fn load(&self, path: &str) -> gpui::Result<Option<Cow<'static, [u8]>>> {
        // Ours, then the component's, then the file-type set. The
        // component's table comes **before** the file icons on purpose:
        // both live under `icons/`, and a file-type icon that one day
        // shares a name would otherwise be served to a button.
        let found = UI
            .iter()
            .chain(COMPONENT.iter())
            .chain(NODES.iter())
            .find(|(name, _)| *name == path)
            .map(|(_, bytes)| *bytes);
        Ok(found
            .or_else(|| path.strip_prefix("icons/").and_then(embed::bytes))
            .map(Cow::Borrowed))
    }

    fn list(&self, path: &str) -> gpui::Result<Vec<SharedString>> {
        Ok(if path.trim_end_matches('/') == "icons" {
            embed::NAMES
                .iter()
                .map(|n| SharedString::from(*n))
                .collect()
        } else {
            Vec::new()
        })
    }
}
